import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"11. 자주 묻는 질문(FAQ) 및 문제 해결","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),o={name:"faq.md"};function e(h,a,n,s,p,d){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_11-자주-묻는-질문-faq-및-문제-해결" tabindex="-1">11. 자주 묻는 질문(FAQ) 및 문제 해결 <a class="header-anchor" href="#_11-자주-묻는-질문-faq-및-문제-해결" aria-label="Permalink to &quot;11. 자주 묻는 질문(FAQ) 및 문제 해결&quot;">​</a></h1><p>인포디오 CMS를 이용하는 과정에서 발생할 수 있는 주요 문제와 해결 방법을 안내합니다.</p><p>문제가 발생한 경우 아래 내용을 참고하여 설정 상태와 입력 정보를 확인해 주세요.</p><p>안내된 방법으로 해결되지 않는 경우 인포디오 운영사에 문의해 주세요.</p><h2 id="_11-1-로그인-및-계정-관련" tabindex="-1">11.1. 로그인 및 계정 관련 <a class="header-anchor" href="#_11-1-로그인-및-계정-관련" aria-label="Permalink to &quot;11.1. 로그인 및 계정 관련&quot;">​</a></h2><h3 id="q1-cms에-로그인이-되지-않습니다" tabindex="-1">Q1. CMS에 로그인이 되지 않습니다. <a class="header-anchor" href="#q1-cms에-로그인이-되지-않습니다" aria-label="Permalink to &quot;Q1. CMS에 로그인이 되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>이메일 주소와 비밀번호를 정확하게 입력했는지 확인합니다.</li><li>영문 대소문자 및 특수문자가 올바르게 입력되었는지 확인합니다.</li><li>브라우저를 새로고침한 후 다시 로그인합니다.</li><li>비밀번호를 잊어버린 경우 비밀번호 재설정 기능을 이용합니다.</li></ol><p>문제가 지속되는 경우 인포디오 운영사에 문의해 주세요.</p><h3 id="q2-비밀번호를-잊어버렸습니다" tabindex="-1">Q2. 비밀번호를 잊어버렸습니다. <a class="header-anchor" href="#q2-비밀번호를-잊어버렸습니다" aria-label="Permalink to &quot;Q2. 비밀번호를 잊어버렸습니다.&quot;">​</a></h3><p>로그인 화면에서 비밀번호 재설정 기능을 이용할 수 있습니다.</p><ol><li>로그인 화면의 <strong>메일로 비밀번호 재설정 링크 전송</strong> 버튼을 클릭합니다.</li><li>등록된 이메일 주소를 입력합니다.</li><li>수신한 이메일의 비밀번호 재설정 링크로 이동합니다.</li><li>새로운 비밀번호를 설정합니다.</li></ol><p>자세한 내용은 <strong>2.2. 비밀번호 재설정</strong>을 참고해 주세요.</p><h3 id="q3-로그인-후-프로젝트가-보이지-않습니다" tabindex="-1">Q3. 로그인 후 프로젝트가 보이지 않습니다. <a class="header-anchor" href="#q3-로그인-후-프로젝트가-보이지-않습니다" aria-label="Permalink to &quot;Q3. 로그인 후 프로젝트가 보이지 않습니다.&quot;">​</a></h3><p>프로젝트는 인포디오 운영사에서 생성하고 고객사 계정에 할당합니다.</p><p>프로젝트가 보이지 않는 경우 다음 사항을 확인해 주세요.</p><ol><li>올바른 계정으로 로그인했는지 확인합니다.</li><li>프로젝트 목록에서 조회 연도를 확인합니다.</li><li>페이지를 새로고침합니다.</li><li>문제가 지속되면 프로젝트 접근 권한을 확인할 수 있도록 인포디오 운영사에 문의합니다.</li></ol><h3 id="q4-새로운-프로젝트를-만들고-싶습니다" tabindex="-1">Q4. 새로운 프로젝트를 만들고 싶습니다. <a class="header-anchor" href="#q4-새로운-프로젝트를-만들고-싶습니다" aria-label="Permalink to &quot;Q4. 새로운 프로젝트를 만들고 싶습니다.&quot;">​</a></h3><p>고객사 계정에서는 프로젝트를 직접 생성할 수 없습니다.</p><p>새로운 축제 또는 행사 프로젝트가 필요한 경우 인포디오 운영사에 프로젝트 생성을 요청해 주세요.</p><hr><h2 id="_11-2-프로젝트-설정-관련" tabindex="-1">11.2. 프로젝트 설정 관련 <a class="header-anchor" href="#_11-2-프로젝트-설정-관련" aria-label="Permalink to &quot;11.2. 프로젝트 설정 관련&quot;">​</a></h2><h3 id="q5-프로젝트의-안내-페이지-주소를-변경할-수-있나요" tabindex="-1">Q5. 프로젝트의 안내 페이지 주소를 변경할 수 있나요? <a class="header-anchor" href="#q5-프로젝트의-안내-페이지-주소를-변경할-수-있나요" aria-label="Permalink to &quot;Q5. 프로젝트의 안내 페이지 주소를 변경할 수 있나요?&quot;">​</a></h3><p>프로젝트 URL Slug는 프로젝트 생성 시 설정되는 고유 식별자이며, 고객사가 직접 변경할 수 없습니다.</p><p>안내 페이지 주소 변경이 필요한 경우 인포디오 운영사에 문의해 주세요.</p><h3 id="q6-안내-페이지에-접속했는데-준비중-화면이-표시됩니다" tabindex="-1">Q6. 안내 페이지에 접속했는데 준비중 화면이 표시됩니다. <a class="header-anchor" href="#q6-안내-페이지에-접속했는데-준비중-화면이-표시됩니다" aria-label="Permalink to &quot;Q6. 안내 페이지에 접속했는데 준비중 화면이 표시됩니다.&quot;">​</a></h3><p>프로젝트 상태가 <strong>준비중</strong>으로 설정되어 있기 때문일 수 있습니다.</p><p>안내 페이지를 방문객에게 공개하려면 다음과 같이 설정해 주세요.</p><ol><li><strong>프로젝트 설정 &gt; 기본 정보</strong>로 이동합니다.</li><li>프로젝트 상태를 <strong>활성화</strong>로 변경합니다.</li><li>변경 내용을 저장합니다.</li><li>안내 페이지에 다시 접속하여 확인합니다.</li></ol><h3 id="q7-안내-페이지에-접속해도-아무것도-표시되지-않습니다" tabindex="-1">Q7. 안내 페이지에 접속해도 아무것도 표시되지 않습니다. <a class="header-anchor" href="#q7-안내-페이지에-접속해도-아무것도-표시되지-않습니다" aria-label="Permalink to &quot;Q7. 안내 페이지에 접속해도 아무것도 표시되지 않습니다.&quot;">​</a></h3><p>프로젝트가 <strong>비활성화</strong> 상태인지 확인해 주세요.</p><ol><li>CMS에서 프로젝트 관리 화면으로 이동합니다.</li><li><strong>프로젝트 설정 &gt; 기본 정보</strong>를 선택합니다.</li><li>프로젝트 상태를 확인합니다.</li><li>필요한 경우 <strong>활성화</strong>로 변경하고 저장합니다.</li></ol><p>프로젝트가 활성화 상태인데도 접속되지 않는다면 인터넷 연결 상태를 확인한 후 운영사에 문의해 주세요.</p><h3 id="q8-프로젝트의-로고나-색상을-변경하고-싶습니다" tabindex="-1">Q8. 프로젝트의 로고나 색상을 변경하고 싶습니다. <a class="header-anchor" href="#q8-프로젝트의-로고나-색상을-변경하고-싶습니다" aria-label="Permalink to &quot;Q8. 프로젝트의 로고나 색상을 변경하고 싶습니다.&quot;">​</a></h3><p><strong>프로젝트 설정 &gt; 브랜딩</strong> 메뉴에서 변경할 수 있습니다.</p><p>로고, 대표 색상, 강조 색상 및 글꼴 등을 수정한 후 저장해 주세요.</p><p>자세한 내용은 <strong>3.3. 프로젝트 브랜딩 설정</strong>을 참고해 주세요.</p><h3 id="q9-특정-서비스-메뉴가-표시되지-않습니다" tabindex="-1">Q9. 특정 서비스 메뉴가 표시되지 않습니다. <a class="header-anchor" href="#q9-특정-서비스-메뉴가-표시되지-않습니다" aria-label="Permalink to &quot;Q9. 특정 서비스 메뉴가 표시되지 않습니다.&quot;">​</a></h3><p>프로젝트에서 해당 서비스 모듈이 활성화되어 있는지 확인해 주세요.</p><ol><li><strong>프로젝트 설정 &gt; 모듈</strong> 메뉴로 이동합니다.</li><li>필요한 모듈이 활성화되어 있는지 확인합니다.</li><li>필요한 경우 해당 모듈을 활성화하고 저장합니다.</li><li>방문객용 하단 메뉴라면 바텀 내비게이션 설정도 확인합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>서비스 모듈의 활성화 상태와 하단 내비게이션의 메뉴 구성은 별도로 관리됩니다.</p></blockquote><h3 id="q10-다국어를-추가했는데-번역된-콘텐츠가-표시되지-않습니다" tabindex="-1">Q10. 다국어를 추가했는데 번역된 콘텐츠가 표시되지 않습니다. <a class="header-anchor" href="#q10-다국어를-추가했는데-번역된-콘텐츠가-표시되지-않습니다" aria-label="Permalink to &quot;Q10. 다국어를 추가했는데 번역된 콘텐츠가 표시되지 않습니다.&quot;">​</a></h3><p>프로젝트에 지원 언어를 추가했더라도 개별 콘텐츠의 번역 정보가 등록되지 않았다면 해당 언어로 표시되지 않을 수 있습니다.</p><p>다음 사항을 확인해 주세요.</p><ol><li><strong>프로젝트 설정 &gt; 다국어</strong>에서 언어가 활성화되어 있는지 확인합니다.</li><li>해당 콘텐츠에 필요한 언어별 정보가 등록되어 있는지 확인합니다.</li><li>변경 내용을 저장합니다.</li><li>방문객용 안내 페이지에서 언어를 변경하여 확인합니다.</li></ol><hr><h2 id="_11-3-홈-화면-및-콘텐츠-관련" tabindex="-1">11.3. 홈 화면 및 콘텐츠 관련 <a class="header-anchor" href="#_11-3-홈-화면-및-콘텐츠-관련" aria-label="Permalink to &quot;11.3. 홈 화면 및 콘텐츠 관련&quot;">​</a></h2><h3 id="q11-메인-배너를-등록했는데-화면에-표시되지-않습니다" tabindex="-1">Q11. 메인 배너를 등록했는데 화면에 표시되지 않습니다. <a class="header-anchor" href="#q11-메인-배너를-등록했는데-화면에-표시되지-않습니다" aria-label="Permalink to &quot;Q11. 메인 배너를 등록했는데 화면에 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>배너 이미지가 정상적으로 등록되었는지 확인합니다.</li><li>배너 추가 후 <strong>저장</strong> 버튼을 클릭했는지 확인합니다.</li><li>프로젝트의 홈 화면 관련 설정을 확인합니다.</li><li>방문객용 안내 페이지를 새로고침합니다.</li></ol><h3 id="q12-이미지가-깨지거나-정상적으로-표시되지-않습니다" tabindex="-1">Q12. 이미지가 깨지거나 정상적으로 표시되지 않습니다. <a class="header-anchor" href="#q12-이미지가-깨지거나-정상적으로-표시되지-않습니다" aria-label="Permalink to &quot;Q12. 이미지가 깨지거나 정상적으로 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ul><li>지원하는 이미지 형식인지 확인</li><li>이미지 파일이 정상적으로 업로드되었는지 확인</li><li>이미지 파일 크기가 등록 제한을 초과하지 않았는지 확인</li><li>원본 이미지가 손상되지 않았는지 확인</li><li>인터넷 연결 상태 확인</li></ul><p>문제가 지속된다면 다른 이미지 파일로 교체하여 확인해 주세요.</p><h3 id="q13-하이라이트에서-원하는-콘텐츠가-상단에-표시되지-않습니다" tabindex="-1">Q13. 하이라이트에서 원하는 콘텐츠가 상단에 표시되지 않습니다. <a class="header-anchor" href="#q13-하이라이트에서-원하는-콘텐츠가-상단에-표시되지-않습니다" aria-label="Permalink to &quot;Q13. 하이라이트에서 원하는 콘텐츠가 상단에 표시되지 않습니다.&quot;">​</a></h3><p>하이라이트는 <strong>실제 조회수와 관리자가 설정한 가중치를 합산한 값</strong>을 기준으로 노출 순위가 결정됩니다.</p><p><code>노출 기준 조회수 = 실제 조회수 + 설정 가중치</code></p><p>예를 들어 실제 조회수 200회인 콘텐츠에 가중치 1,000을 설정하면 노출 기준 조회수는 1,200회가 됩니다.</p><p>원하는 콘텐츠가 상단에 표시되지 않는 경우 해당 콘텐츠의 가중치와 하이라이트 표시 개수를 확인해 주세요.</p><h3 id="q14-행사-일정이-방문객-화면에-표시되지-않습니다" tabindex="-1">Q14. 행사 일정이 방문객 화면에 표시되지 않습니다. <a class="header-anchor" href="#q14-행사-일정이-방문객-화면에-표시되지-않습니다" aria-label="Permalink to &quot;Q14. 행사 일정이 방문객 화면에 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>일정이 정상적으로 등록되어 있는지 확인합니다.</li><li>일정의 시작일과 종료일이 올바른지 확인합니다.</li><li>해당 일정의 공개 관련 설정을 확인합니다.</li><li>프로젝트에서 일정 모듈이 활성화되어 있는지 확인합니다.</li><li>변경 내용을 저장하고 방문객 화면에서 다시 확인합니다.</li></ol><h3 id="q15-상세-콘텐츠를-삭제해도-되나요" tabindex="-1">Q15. 상세 콘텐츠를 삭제해도 되나요? <a class="header-anchor" href="#q15-상세-콘텐츠를-삭제해도-되나요" aria-label="Permalink to &quot;Q15. 상세 콘텐츠를 삭제해도 되나요?&quot;">​</a></h3><p>상세 콘텐츠는 일정, 지도 객체, 비디오 가이드 등 다른 기능과 연결되어 있을 수 있습니다.</p><p>콘텐츠를 삭제하면 연결된 화면에 영향을 줄 수 있으므로 삭제 전에 관련 서비스에서 해당 콘텐츠를 사용하고 있는지 확인해 주세요.</p><h3 id="q16-공지사항을-실수로-노출-종료했습니다" tabindex="-1">Q16. 공지사항을 실수로 노출 종료했습니다. <a class="header-anchor" href="#q16-공지사항을-실수로-노출-종료했습니다" aria-label="Permalink to &quot;Q16. 공지사항을 실수로 노출 종료했습니다.&quot;">​</a></h3><p>공지사항은 노출이 종료되더라도 이력에 보관됩니다.</p><p><strong>복구 방법</strong></p><ol><li><strong>공지사항</strong> 메뉴로 이동합니다.</li><li><strong>이력 목록</strong>을 확인합니다.</li><li>다시 노출할 공지사항을 찾습니다.</li><li>재노출 기능을 이용합니다.</li><li>현재 노출 목록에 추가되었는지 확인합니다.</li></ol><hr><h2 id="_11-4-투어맵-관련" tabindex="-1">11.4. 투어맵 관련 <a class="header-anchor" href="#_11-4-투어맵-관련" aria-label="Permalink to &quot;11.4. 투어맵 관련&quot;">​</a></h2><h3 id="q17-투어맵의-다른-관리-기능을-사용할-수-없습니다" tabindex="-1">Q17. 투어맵의 다른 관리 기능을 사용할 수 없습니다. <a class="header-anchor" href="#q17-투어맵의-다른-관리-기능을-사용할-수-없습니다" aria-label="Permalink to &quot;Q17. 투어맵의 다른 관리 기능을 사용할 수 없습니다.&quot;">​</a></h3><p><strong>지도 기본 설정이 저장되지 않았을 가능성</strong>이 있습니다.</p><p>투어맵의 다른 관리 기능을 사용하려면 지도 기본 설정을 먼저 완료해야 합니다.</p><ol><li><strong>투어맵 기본 설정</strong> 메뉴로 이동합니다.</li><li>지도 중심 좌표와 줌 레벨 등을 설정합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li><li>저장이 완료되면 다른 지도 관리 기능을 확인합니다.</li></ol><h3 id="q18-지도에-등록한-마커가-표시되지-않습니다" tabindex="-1">Q18. 지도에 등록한 마커가 표시되지 않습니다. <a class="header-anchor" href="#q18-지도에-등록한-마커가-표시되지-않습니다" aria-label="Permalink to &quot;Q18. 지도에 등록한 마커가 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>마커가 올바른 위치에 등록되어 있는지 확인합니다.</li><li>위도와 경도가 정확한지 확인합니다.</li><li>마커의 최소·최대 줌 레벨을 확인합니다.</li><li>마커 이미지가 정상적으로 등록되어 있는지 확인합니다.</li><li>변경 내용을 저장했는지 확인합니다.</li></ol><p>특정 확대 수준에서만 표시되도록 설정된 마커는 현재 지도 줌 레벨에 따라 보이지 않을 수 있습니다.</p><h3 id="q19-지도-객체를-선택해도-바텀시트가-표시되지-않습니다" tabindex="-1">Q19. 지도 객체를 선택해도 바텀시트가 표시되지 않습니다. <a class="header-anchor" href="#q19-지도-객체를-선택해도-바텀시트가-표시되지-않습니다" aria-label="Permalink to &quot;Q19. 지도 객체를 선택해도 바텀시트가 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>해당 객체의 <strong>클릭 시 이벤트 설정</strong>을 확인합니다.</li><li>바텀시트 유형이 <strong>표시 안 함</strong>으로 설정되어 있는지 확인합니다.</li><li>단일 POI 또는 POI 목록형인 경우 상세 콘텐츠가 정상적으로 연결되어 있는지 확인합니다.</li><li>단순정보형인 경우 필요한 정보가 입력되어 있는지 확인합니다.</li><li>변경 내용을 저장하고 다시 확인합니다.</li></ol><h3 id="q20-목록형-바텀시트에-콘텐츠가-표시되지-않습니다" tabindex="-1">Q20. 목록형 바텀시트에 콘텐츠가 표시되지 않습니다. <a class="header-anchor" href="#q20-목록형-바텀시트에-콘텐츠가-표시되지-않습니다" aria-label="Permalink to &quot;Q20. 목록형 바텀시트에 콘텐츠가 표시되지 않습니다.&quot;">​</a></h3><p>POI 목록 바텀시트는 등록된 상세 콘텐츠를 직접 매핑하는 방식입니다.</p><p>지도에 등록된 마커가 자동으로 목록에 추가되지는 않습니다.</p><p><strong>확인 방법</strong></p><ol><li>바텀시트를 설정한 지도 객체를 선택합니다.</li><li>바텀시트 유형이 <strong>POI 목록</strong>인지 확인합니다.</li><li>목록에 표시할 상세 콘텐츠가 연결되어 있는지 확인합니다.</li><li>필요한 콘텐츠를 추가로 매핑합니다.</li><li>설정을 저장합니다.</li></ol><h3 id="q21-행사장-이미지가-실제-지도-위치와-맞지-않습니다" tabindex="-1">Q21. 행사장 이미지가 실제 지도 위치와 맞지 않습니다. <a class="header-anchor" href="#q21-행사장-이미지가-실제-지도-위치와-맞지-않습니다" aria-label="Permalink to &quot;Q21. 행사장 이미지가 실제 지도 위치와 맞지 않습니다.&quot;">​</a></h3><p>지리 참조 이미지의 위치와 크기를 조정해 주세요.</p><ol><li><strong>지리 참조 이미지</strong> 레이어를 선택합니다.</li><li>수정할 이미지를 선택합니다.</li><li>지도 위에서 이미지의 위치와 크기를 조정합니다.</li><li>실제 행사장 위치와 일치하는지 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><hr><h2 id="_11-5-스탬프-투어-관련" tabindex="-1">11.5. 스탬프 투어 관련 <a class="header-anchor" href="#_11-5-스탬프-투어-관련" aria-label="Permalink to &quot;11.5. 스탬프 투어 관련&quot;">​</a></h2><h3 id="q22-스탬프-투어-화면이-표시되지-않습니다" tabindex="-1">Q22. 스탬프 투어 화면이 표시되지 않습니다. <a class="header-anchor" href="#q22-스탬프-투어-화면이-표시되지-않습니다" aria-label="Permalink to &quot;Q22. 스탬프 투어 화면이 표시되지 않습니다.&quot;">​</a></h3><p><strong>프로젝트 설정 &gt; 모듈</strong>에서 스탬프 투어 모듈이 활성화되어 있는지 확인해 주세요.</p><p>모듈이 활성화되어 있다면 스탬프 코스 및 지점이 정상적으로 등록되어 있는지 확인합니다.</p><h3 id="q23-스탬프-qr-코드가-표시되지-않습니다" tabindex="-1">Q23. 스탬프 QR 코드가 표시되지 않습니다. <a class="header-anchor" href="#q23-스탬프-qr-코드가-표시되지-않습니다" aria-label="Permalink to &quot;Q23. 스탬프 QR 코드가 표시되지 않습니다.&quot;">​</a></h3><p>QR 코드와 인증코드는 스탬프 지점을 저장한 후 확인할 수 있습니다.</p><p>신규 스탬프를 등록한 경우 먼저 저장을 완료한 후 상세 화면에서 확인해 주세요.</p><h3 id="q24-스탬프가-수집되지-않습니다" tabindex="-1">Q24. 스탬프가 수집되지 않습니다. <a class="header-anchor" href="#q24-스탬프가-수집되지-않습니다" aria-label="Permalink to &quot;Q24. 스탬프가 수집되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ul><li>해당 스탬프의 운영 기간</li><li>QR 코드 또는 인증코드의 정확성</li><li>방문객의 네트워크 연결 상태</li><li>해당 스탬프의 기존 수집 여부</li></ul><p>문제가 지속된다면 해당 스탬프의 이름과 인증 시도 시각을 확인하여 인포디오 운영사에 문의해 주세요.</p><h3 id="q25-스탬프를-모두-모았는데-완주-처리되지-않습니다" tabindex="-1">Q25. 스탬프를 모두 모았는데 완주 처리되지 않습니다. <a class="header-anchor" href="#q25-스탬프를-모두-모았는데-완주-처리되지-않습니다" aria-label="Permalink to &quot;Q25. 스탬프를 모두 모았는데 완주 처리되지 않습니다.&quot;">​</a></h3><p>스탬프 코스의 <strong>완주 기준</strong> 설정을 확인해 주세요.</p><p>완주 기준은 운영 날짜와 해당 날짜의 스탬프 구성에 따라 달라질 수 있습니다.</p><ol><li><strong>스탬프 코스 관리</strong>에서 해당 코스를 선택합니다.</li><li>날짜별 완주 기준을 확인합니다.</li><li>방문객이 수집한 스탬프가 기준을 충족하는지 확인합니다.</li></ol><h3 id="q26-방문객에게-보상을-지급할-수-없습니다" tabindex="-1">Q26. 방문객에게 보상을 지급할 수 없습니다. <a class="header-anchor" href="#q26-방문객에게-보상을-지급할-수-없습니다" aria-label="Permalink to &quot;Q26. 방문객에게 보상을 지급할 수 없습니다.&quot;">​</a></h3><p>스탬프 보상은 CMS가 아니라 <strong>협력업체용 보상 지급 페이지</strong>에서 처리합니다.</p><p>다음 사항을 확인해 주세요.</p><ol><li>방문객이 코스 완주 기준을 충족했는지 확인합니다.</li><li>보상 정책의 운영 기간을 확인합니다.</li><li>이미 보상을 수령했는지 확인합니다.</li><li>날짜별 보상 수량 제한을 확인합니다.</li><li>협력업체용 보상 지급 페이지에서 지급 가능 상태를 확인합니다.</li></ol><hr><h2 id="_11-6-부가-서비스-관련" tabindex="-1">11.6. 부가 서비스 관련 <a class="header-anchor" href="#_11-6-부가-서비스-관련" aria-label="Permalink to &quot;11.6. 부가 서비스 관련&quot;">​</a></h2><h3 id="q27-ai-챗봇의-답변이-실제-행사-정보와-다릅니다" tabindex="-1">Q27. AI 챗봇의 답변이 실제 행사 정보와 다릅니다. <a class="header-anchor" href="#q27-ai-챗봇의-답변이-실제-행사-정보와-다릅니다" aria-label="Permalink to &quot;Q27. AI 챗봇의 답변이 실제 행사 정보와 다릅니다.&quot;">​</a></h3><p>AI 챗봇은 부정확한 정보를 안내할 가능성이 있습니다.</p><p>우선 관련 행사 일정, 상세 콘텐츠, 지도 정보 및 공지사항이 최신 상태인지 확인해 주세요.</p><p>등록된 정보가 정확한데도 잘못된 답변이 반복된다면 질문 내용과 답변을 확인하여 인포디오 운영사에 문의해 주세요.</p><h3 id="q28-설문조사가-방문객에게-표시되지-않습니다" tabindex="-1">Q28. 설문조사가 방문객에게 표시되지 않습니다. <a class="header-anchor" href="#q28-설문조사가-방문객에게-표시되지-않습니다" aria-label="Permalink to &quot;Q28. 설문조사가 방문객에게 표시되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>설문 모듈이 활성화되어 있는지 확인합니다.</li><li>설문 공개 여부를 확인합니다.</li><li>설문 시작일과 종료일을 확인합니다.</li><li>설문 질문이 정상적으로 등록되어 있는지 확인합니다.</li><li>변경 내용을 저장하고 다시 확인합니다.</li></ol><h3 id="q29-오디오-가이드를-공개할-수-없습니다" tabindex="-1">Q29. 오디오 가이드를 공개할 수 없습니다. <a class="header-anchor" href="#q29-오디오-가이드를-공개할-수-없습니다" aria-label="Permalink to &quot;Q29. 오디오 가이드를 공개할 수 없습니다.&quot;">​</a></h3><p>프로젝트에서 지원하는 언어별 음성이 모두 생성되지 않은 경우 오디오 가이드가 <strong>준비 중</strong> 상태로 유지될 수 있습니다.</p><p>다음 사항을 확인해 주세요.</p><ol><li>각 언어의 스크립트가 작성되어 있는지 확인합니다.</li><li>언어별 음성이 생성되었는지 확인합니다.</li><li>스크립트나 음성 설정을 변경했다면 음성을 다시 생성합니다.</li><li>모든 언어의 음성이 준비되면 공개 상태를 설정합니다.</li></ol><h3 id="q30-위치-기반-오디오-가이드가-자동-재생되지-않습니다" tabindex="-1">Q30. 위치 기반 오디오 가이드가 자동 재생되지 않습니다. <a class="header-anchor" href="#q30-위치-기반-오디오-가이드가-자동-재생되지-않습니다" aria-label="Permalink to &quot;Q30. 위치 기반 오디오 가이드가 자동 재생되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ul><li>위치 기반 자동 재생 좌표가 올바른지 확인</li><li>자동 재생 범위가 0미터로 설정되어 있지 않은지 확인</li><li>모바일 브라우저에서 위치 권한이 허용되어 있는지 확인</li><li>방문객이 설정된 위치 범위에 진입했는지 확인</li><li>모바일 브라우저의 자동 재생 제한 여부 확인</li></ul><blockquote><p><strong>참고</strong></p><p>위치 기반 자동 재생은 모바일 기기 및 브라우저 환경에 영향을 받을 수 있습니다.</p></blockquote><h3 id="q31-비디오-가이드가-재생되지-않습니다" tabindex="-1">Q31. 비디오 가이드가 재생되지 않습니다. <a class="header-anchor" href="#q31-비디오-가이드가-재생되지-않습니다" aria-label="Permalink to &quot;Q31. 비디오 가이드가 재생되지 않습니다.&quot;">​</a></h3><p>다음 사항을 확인해 주세요.</p><ol><li>영상 파일이 정상적으로 업로드되었는지 확인합니다.</li><li>해당 언어의 영상이 등록되어 있는지 확인합니다.</li><li>영상이 올바른 상세 콘텐츠에 연결되어 있는지 확인합니다.</li><li>인터넷 연결 상태를 확인합니다.</li><li>다른 브라우저에서도 동일한 문제가 발생하는지 확인합니다.</li></ol><hr><h2 id="_11-7-통계-및-대시보드-관련" tabindex="-1">11.7. 통계 및 대시보드 관련 <a class="header-anchor" href="#_11-7-통계-및-대시보드-관련" aria-label="Permalink to &quot;11.7. 통계 및 대시보드 관련&quot;">​</a></h2><h3 id="q32-방문-사용자-수와-실제-행사장-방문객-수가-다릅니다" tabindex="-1">Q32. 방문 사용자 수와 실제 행사장 방문객 수가 다릅니다. <a class="header-anchor" href="#q32-방문-사용자-수와-실제-행사장-방문객-수가-다릅니다" aria-label="Permalink to &quot;Q32. 방문 사용자 수와 실제 행사장 방문객 수가 다릅니다.&quot;">​</a></h3><p>대시보드의 방문 사용자 수는 안내 페이지를 이용한 사용자를 기준으로 집계됩니다.</p><p>실제 행사장을 방문했더라도 안내 페이지를 이용하지 않은 방문객은 포함되지 않을 수 있습니다.</p><p>따라서 대시보드의 사용자 수와 현장의 실제 입장객 수는 차이가 발생할 수 있습니다.</p><h3 id="q33-동시-접속-사용자-수가-실제-접속자-수와-다릅니다" tabindex="-1">Q33. 동시 접속 사용자 수가 실제 접속자 수와 다릅니다. <a class="header-anchor" href="#q33-동시-접속-사용자-수가-실제-접속자-수와-다릅니다" aria-label="Permalink to &quot;Q33. 동시 접속 사용자 수가 실제 접속자 수와 다릅니다.&quot;">​</a></h3><p>동시 접속 사용자 수는 최근 5분 이내 안내 페이지를 이용한 사용자를 기준으로 표시됩니다.</p><p>정확히 같은 순간에 접속한 사용자 수를 의미하지 않으므로 실제 접속 현황과 차이가 있을 수 있습니다.</p><h3 id="q34-혼잡도-지도에-실제-현장-상황이-정확하게-반영되지-않습니다" tabindex="-1">Q34. 혼잡도 지도에 실제 현장 상황이 정확하게 반영되지 않습니다. <a class="header-anchor" href="#q34-혼잡도-지도에-실제-현장-상황이-정확하게-반영되지-않습니다" aria-label="Permalink to &quot;Q34. 혼잡도 지도에 실제 현장 상황이 정확하게 반영되지 않습니다.&quot;">​</a></h3><p>혼잡도는 최근 5분 이내 위치 정보를 전송한 사용자를 기준으로 계산하는 추정 데이터입니다.</p><p>위치 정보 제공 여부, 위치 정확도, 이용자 수 등에 따라 실제 혼잡 상태와 차이가 발생할 수 있습니다.</p><p>혼잡도는 현장 운영 상황을 파악하기 위한 참고 자료로 활용해 주세요.</p><h3 id="q35-날짜를-변경했는데-일부-통계가-바뀌지-않습니다" tabindex="-1">Q35. 날짜를 변경했는데 일부 통계가 바뀌지 않습니다. <a class="header-anchor" href="#q35-날짜를-변경했는데-일부-통계가-바뀌지-않습니다" aria-label="Permalink to &quot;Q35. 날짜를 변경했는데 일부 통계가 바뀌지 않습니다.&quot;">​</a></h3><p>대시보드에는 <strong>기간별 통계와 실시간 통계</strong>가 함께 표시됩니다.</p><p>날짜 선택은 방문 사용자 수, 시간대별 활성 사용자, 서비스 이용 현황 등의 기간별 통계에 적용됩니다.</p><p>동시 접속 사용자 수, 실시간 혼잡도, 주요 이벤트, 챗봇 질문 이력 등은 선택한 날짜와 관계없이 최신 정보를 표시합니다.</p><hr><h2 id="_11-8-문제-해결이-어려운-경우" tabindex="-1">11.8. 문제 해결이 어려운 경우 <a class="header-anchor" href="#_11-8-문제-해결이-어려운-경우" aria-label="Permalink to &quot;11.8. 문제 해결이 어려운 경우&quot;">​</a></h2><p>위의 방법으로 문제가 해결되지 않는다면 인포디오 운영사에 문의해 주세요.</p><p>정확한 문제 확인을 위해 다음 정보를 함께 전달하면 더욱 원활한 지원을 받을 수 있습니다.</p><h3 id="_1-문의-시-필요한-정보" tabindex="-1">① 문의 시 필요한 정보 <a class="header-anchor" href="#_1-문의-시-필요한-정보" aria-label="Permalink to &quot;① 문의 시 필요한 정보&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>프로젝트 명</td><td>문제가 발생한 프로젝트 이름</td></tr><tr><td>발생 일시</td><td>문제가 발생한 날짜와 시간</td></tr><tr><td>발생 메뉴</td><td>문제가 발생한 CMS 메뉴</td></tr><tr><td>문제 내용</td><td>어떤 동작에서 문제가 발생했는지 설명</td></tr><tr><td>오류 메시지</td><td>화면에 표시된 오류 문구</td></tr><tr><td>화면 캡처</td><td>오류 화면 또는 문제가 발생한 상태의 이미지</td></tr><tr><td>사용 환경</td><td>사용한 브라우저 및 기기 종류</td></tr></tbody></table><h3 id="_2-문의-내용-작성-예시" tabindex="-1">② 문의 내용 작성 예시 <a class="header-anchor" href="#_2-문의-내용-작성-예시" aria-label="Permalink to &quot;② 문의 내용 작성 예시&quot;">​</a></h3><p><strong>프로젝트:</strong> 가을 문화 축제</p><p><strong>발생 일시:</strong> 2026.10.15 14:30</p><p><strong>발생 메뉴:</strong> 투어맵 &gt; 구역 오버레이</p><p><strong>문제 내용:</strong> 맞춤형 마커를 추가한 후 저장했지만 방문객용 지도에 표시되지 않습니다.</p><p><strong>확인한 사항:</strong> 마커 위치와 줌 레벨을 확인했으며, 새로고침 후에도 동일한 문제가 발생합니다.</p><p><strong>사용 환경:</strong> Windows 11 / Chrome</p><p><strong>첨부 자료:</strong> CMS 설정 화면 및 방문객용 지도 화면 캡처</p><blockquote><p><strong>참고</strong></p><p>문의 시 비밀번호, 인증 토큰 등 계정의 민감한 정보가 포함되지 않도록 주의해 주세요.</p><p>필요한 경우 인포디오 운영사의 안내에 따라 추가 정보를 전달해 주세요.</p></blockquote>',162)])])}const u=l(o,[["render",e]]);export{c as __pageData,u as default};
